begin;
insert into auth.users(id,email,raw_user_meta_data) values('30000000-0000-4000-8000-000000000001','page-test-admin@example.invalid','{"full_name":"Page test","requested_role":"membre","motivation":"Temporary page editor test","city":"Yaoundé","region":"Centre","phone":"+237600000000"}'),('30000000-0000-4000-8000-000000000002','page-test-member@example.invalid','{"full_name":"Page test","requested_role":"membre","motivation":"Temporary page editor test","city":"Yaoundé","region":"Centre","phone":"+237600000000"}');
update public.profiles set status='approved',role=case right(id::text,1) when '1' then 'admin' else 'membre' end where id::text like '30000000-0000-4000-8000-%';
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000002',true);
set local role authenticated;
do $$begin begin perform public.save_managed_page('/about','[]',false,0);raise exception 'FAILED member editor';exception when insufficient_privilege then null;end;begin update public.managed_pages set live_document='[]';raise exception 'FAILED direct page update';exception when insufficient_privilege then null;end;end$$;
reset role;
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000001',true);
set local role authenticated;
do $$declare b jsonb; r bigint; denied boolean:=false;begin
 b:='[{"type":"paragraph","fr":"Texte français","en":"","align":"left","font":"century","size":"20","color":"#166534","width":"100","crop":"auto","position":"center","bold":false,"italic":false,"underline":false}]';
 select revision into r from public.managed_pages where path='/about';r:=coalesce(r,0);
 perform public.save_managed_page('/about',b,false,r);r:=r+1;
 begin perform public.save_managed_page('/about',b,true,r);exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'FAILED missing English publication';end if;
 b:=jsonb_set(b,'{0,en}','"English text"');
 perform public.save_managed_page('/about',b,true,r);r:=r+1;
 begin perform public.save_managed_page('/about',b,true,r-1);raise exception 'FAILED concurrent overwrite';exception when serialization_failure then null;end;
 denied:=false;begin perform public.save_managed_page('/about',b,true,null);exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAILED null revision bypass';end if;
 denied:=false;begin perform public.save_managed_page('/about',null,false,r);exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAILED null document bypass';end if;
 b:=jsonb_set(b,'{0,font}','"unsafe-font"');denied:=false;
 begin perform public.save_managed_page('/about',b,true,r);exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'FAILED format bypass';end if;
 if (select count(*) from public.managed_page_versions where path='/about')<2 then raise exception 'FAILED history';end if;
end$$;
