select set_config('request.jwt.claim.sub','',true);
set local role anon;
do $$begin if not exists(select 1 from public.managed_pages where path='/about' and live_document->0->>'en'='English text') then raise exception 'FAILED published read';end if;begin perform public.save_managed_page('/about','[]',false,0);raise exception 'FAILED anonymous editor';exception when insufficient_privilege then null;end;begin perform 1 from public.managed_page_versions;raise exception 'FAILED anonymous drafts';exception when insufficient_privilege then null;end;end$$;
reset role;
rollback;
